 Messages exist in English (`en`) and Korean (`ko`), in
 `src/i18n/messages.js`. The server answers in `LARDER_LANG` (default `en`).
+
+## Routes
+
+`POST /batches/:id/transfer` takes `{ "to": "<location id>", "qty": 2 }` and
+answers with the batch now at `to`. Moving the whole batch changes its
+location; moving part of it splits off a new batch (same item, lot, expiry and
+received date) and writes an `adjust` movement on each batch, with `ref`
+`transfer:out:<id>` / `transfer:in:<id>`. Errors: `unknown_batch`,
+`unknown_location`, `invalid_qty` (zero, or more than the batch holds),
+`bad_request` (batch already at `to`).
diff --git a/src/domain/batches.js b/src/domain/batches.js
index ee14fde..baaa63d 100644
--- a/src/domain/batches.js
+++ b/src/domain/batches.js
@@ -55,3 +55,33 @@ export function waste(store, batchId, qty, { at, ref = "" }) {
   batch.qty = Math.round((batch.qty - qty) * 1000) / 1000;
   return record(store, { type: "waste", batchId, qty, at, ref });
 }
+
+/**
+ * Moves `qty` of a batch to location `to`. The whole batch just changes
+ * location; part of it splits off a new batch (same item, lot, expiry and
+ * received date) at `to`. Returns the batch now at `to`.
+ */
+export function transfer(store, batchId, to, qty, { at }) {
+  const batch = getBatch(store, batchId);
+  if (!store.data.locations.some((loc) => loc.id === to)) throw new AppError("unknown_location", { id: to });
+  if (!(qty > 0) || qty > batch.qty) throw new AppError("invalid_qty");
+  if (batch.location === to) throw new AppError("bad_request", { reason: "the batch is already there" });
+  if (qty === batch.qty) {
+    batch.location = to;
+    return batch;
+  }
+  const moved = {
+    id: store.nextId("batch"),
+    itemId: batch.itemId,
+    lot: batch.lot,
+    qty,
+    receivedOn: batch.receivedOn,
+    expires: batch.expires,
+    location: to,
+  };
+  batch.qty = Math.round((batch.qty - qty) * 1000) / 1000;
+  store.data.batches.push(moved);
+  record(store, { type: "adjust", batchId: batch.id, qty, at, ref: `transfer:out:${moved.id}` });
+  record(store, { type: "adjust", batchId: moved.id, qty, at, ref: `transfer:in:${batch.id}` });
+  return moved;
+}
